import{_ as l,l as o,o as e,c as s,v as t,p as P,x as i,d as n,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"多播 IGMP / PIM","description":"","frontmatter":{"title":"多播 IGMP / PIM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/multicast-igmp-pim.md","filePath":"cs/multicast-igmp-pim.md","lastUpdated":1789023840000}'),M={name:"cs/multicast-igmp-pim.md"};function I(c,a,m,h,_,u){const r=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="多播-igmp-pim" tabindex="-1">多播 IGMP / PIM <a class="header-anchor" href="#多播-igmp-pim" aria-label="Permalink to &quot;多播 IGMP / PIM&quot;">​</a></h1><div class="epigraph"><p>接收者用 IGMP/MLD 报名，路由器用 PIM 长树；数据沿树复制，而不是源发 N 份单播。</p><footer>—— 据 RFC 3376 IGMPv3；RFC 7761 PIM-SM；RFC 4601 整理</footer></div><p><a href="/cs/gre-tunnels">上一课</a> 默认单播。<a href="/cs/evpn">EVPN</a> 的 BUM 需要复制。缺口是<strong>IP 多播</strong>：主机报告组，PIM 在路由器间建共享树或源树。本课不把 IPv6 过渡写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直播、股票行情、某些覆盖 BUM：一对多。单播复制在源爆炸。IGMP 在最后一跳问「谁要 239.x」；窥探交换机把组播从泛洪收成端口集合，接住 MAC 学习课的组播痛点。PIM-SM：先加到 RP 共享树，再可切换最短源树。ASM vs SSM：有无显式源。</p><p>不要把多播写成 UDP 不可靠的替代可靠：仍无拥塞控制合同，要应用层或 FEC。</p><p><span class="marginnote">RFC 7761。RP 是共享树根，单点与策略对象。Bidir-PIM 等变体点名。本课不把 MSDP 写完。</span></p><h3 id="树复制不是-n-份单播" tabindex="-1">树复制不是 N 份单播 <a class="header-anchor" href="#树复制不是-n-份单播" aria-label="Permalink to &quot;树复制不是 N 份单播&quot;">​</a></h3><p>IGMP 报名，PIM 建树，窥探收二层泛洪。无内置拥塞控制。跨域多播几乎萎缩。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：主机 IGMP → 叶子路由器 → PIM Join 向上 → 数据向下复制。对照生成树：STP 一棵无环二层树；PIM 按组/源多棵，且是三层。VXLAN 可用 PIM 做底层 BUM。</p>',11)),(e(),P(d,null,{default:i(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22IGMP%20%E6%8A%A5%E5%90%8D%22%5D%20--%3E%20DR%5B%22%E5%8F%B6%E5%AD%90%E8%B7%AF%E7%94%B1%E5%99%A8%22%5D%0A%20%20DR%20--%3E%20JOIN%5B%22PIM%20Join%22%5D%0A%20%20JOIN%20--%3E%20RP%5B%22%E5%85%B1%E4%BA%AB%E6%A0%91%E6%88%96%E6%BA%90%E6%A0%91%22%5D%0A%20%20RP%20--%3E%20REP%5B%22%E6%B2%BF%E6%A0%91%E5%A4%8D%E5%88%B6%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ECMP 与多播：RPF 检查要用到源的单播路由，哈希不当会导致 RPF 失败。TE 显式路径与多播树难叠加。RPKI 不管组播源伪造，需要 ACL 或 SSM。无线上多播常以最低 MCS 发送，吃容量。</p><p>状态：每组每源的树是软状态，规模是运营边界。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 PIM-SSM 的全部部署清单。IPv6 过渡技术是下一课。后课默认：IGMP 报名，PIM 建树，交换机可窥探。</p><p>互联网跨域多播几乎萎缩；域内与数据中心仍常见。</p><p>上一课留下的缺口在本课收口；「多播 IGMP / PIM」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/ipv6-transition">IPv6 过渡技术</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>主机 IGMP，路由器 PIM，树复制。</li><li>窥探把二层组播从广播里收回。</li><li>无内置拥塞控制。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 3376；RFC 7761。</li></ul>',10))])}const f=l(M,[["render",I]]);export{A as __pageData,f as default};
